class Solution:

	def LCP(self, arr, n):
		arr.sort()
		i = 0
		res = ''
		if arr[0][i] != arr[len(arr) - 1][i]:
			return -1
		while i < len(arr[0]) and arr[0][i] == arr[len(arr) - 1][i]:
			res += arr[0][i]
			i += 1
		return res
